const learningRaw = $('Find User Learning').all().map(i => i.json);
const coursesRaw = $('Find Courses').all().map(i => i.json);
const modulesRaw = $('Find Course Modules').all().map(i => i.json);

// Drop empty placeholder items produced by alwaysOutputData when there are no rows
const learning = learningRaw.filter(r => r && r.user_id);

// No learning rows -> return empty course list
if (learning.length === 0) {
  return [{ json: { success: true, count: 0, courses: [] } }];
}

const coursesById = {};
for (const c of coursesRaw) {
  if (c && c.course_id) coursesById[c.course_id] = c;
}

const modulesByCourse = {};
for (const m of modulesRaw) {
  if (!m || !m.course_id) continue;
  (modulesByCourse[m.course_id] = modulesByCourse[m.course_id] || []).push(m);
}

// Learning rows keyed by course_id + module_id, and per-course collections
const learningByCourseModule = {};
const learningByCourse = {};
for (const ul of learning) {
  if (!ul.course_id) continue;
  learningByCourseModule[ul.course_id + '::' + ul.module_id] = ul;
  (learningByCourse[ul.course_id] = learningByCourse[ul.course_id] || []).push(ul);
}

function parseArr(v) {
  if (v === null || v === undefined || v === '') return [];
  if (Array.isArray(v)) return v;
  try {
    const parsed = JSON.parse(v);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

// Unique course_ids present in the user's learning rows
const courseIds = Object.keys(learningByCourse);

const result = [];
for (const courseId of courseIds) {
  const course = coursesById[courseId];
  if (!course) continue;
  if (course.is_active === false) continue;

  const modules = (modulesByCourse[courseId] || [])
    .slice()
    .sort((a, b) => (a.order_index ?? 0) - (b.order_index ?? 0))
    .map(m => {
      const ul = learningByCourseModule[courseId + '::' + m.module_id] || {};
      return {
        module_id: m.module_id,
        course_id: m.course_id ?? courseId,
        order_index: m.order_index ?? 0,
        title: m.title ?? null,
        description: m.description ?? null,
        content: m.content ?? null,
        skill_name: m.skill_name ?? null,
        resources: parseArr(m.resources_json),
        importance_score: m.importance_score ?? 0,
        market_demand_percent: m.market_demand_percent ?? 0,
        trend_percent: m.trend_percent ?? 0,
        status: ul.status ?? 'not_started',
        progress_percent: ul.progress_percent ?? 0,
        started_at: ul.started_at ?? null,
        completed_at: ul.completed_at ?? null,
        score: ul.score ?? null,
      };
    });

  const total_modules = modules.length;
  const completed_modules = modules.filter(m => (m.progress_percent ?? 0) >= 100).length;
  const progress_percent = total_modules > 0
    ? Math.round(modules.reduce((s, m) => s + (m.progress_percent ?? 0), 0) / total_modules)
    : 0;

  let status = 'not_started';
  if (progress_percent >= 100) status = 'completed';
  else if (progress_percent > 0) status = 'in_progress';

  const priority_score = (learningByCourse[courseId] || [])
    .reduce((max, ul) => Math.max(max, ul.priority_score ?? 0), 0);

  result.push({
    course_id: course.course_id,
    name: course.name ?? null,
    description: course.description ?? null,
    role: course.role ?? null,
    version: course.version ?? null,
    jobs_analyzed: course.jobs_analyzed ?? null,
    generated_at: course.generated_at ?? null,
    updated_at: course.updated_at ?? null,

    status,
    progress_percent,
    completed_modules,
    total_modules,
    priority_score,

    modules,
  });
}

result.sort((a, b) => (b.priority_score ?? 0) - (a.priority_score ?? 0));

return [{ json: { success: true, count: result.length, courses: result } }];
